142: /* ══════════ starfield ══════════ */
143: function initStars() {
144:   const canvas = $('#starfield');
145:   const ctx = canvas.getContext('2d');
146:   const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
147:   let w = 0, h = 0, dpr = Math.min(window.devicePixelRatio || 1, 2);
148:   let stars = [], shooting = null, last = performance.now();
149:   function resize() {
150:     w = window.innerWidth; h = window.innerHeight;
151:     canvas.width = w * dpr; canvas.height = h * dpr;
152:     canvas.style.width = w + 'px'; canvas.style.height = h + 'px';
153:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
154:     const count = Math.min(220, Math.round((w * h) / 9000));
155:     stars = Array.from({ length: count }, () => ({
156:       x: Math.random() * w, y: Math.random() * h,
157:       r: Math.random() * 1.2 + 0.25,
158:       a: Math.random() * 0.55 + 0.18,
159:       sp: Math.random() * 0.014 + 0.003,
160:       ph: Math.random() * Math.PI * 2,
161:       hue: Math.random() < 0.16 ? '#e8c987' : Math.random() < 0.4 ? '#c7d6ff' : '#ffffff',
162:     }));
163:   }
164:   function draw(t) {
165:     ctx.clearRect(0, 0, w, h);
166:     const dt = reduced ? 0 : Math.min(48, t - last); last = t;
167:     for (const s of stars) {
168:       s.ph += s.sp * (dt / 16.7);
169:       const alpha = s.a * (0.6 + 0.4 * Math.sin(s.ph));
170:       ctx.globalAlpha = alpha;
171:       ctx.fillStyle = s.hue;
172:       ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill();
173:       if (s.r > 1.05) {
174:         ctx.globalAlpha = alpha * 0.35;
175:         ctx.fillRect(s.x - 3, s.y - 0.3, 6, 0.6);
176:         ctx.fillRect(s.x - 0.3, s.y - 3, 0.6, 6);
177:       }
178:     }
179:     if (!reduced) {
180:       if (!shooting && Math.random() < 0.0025) {
181:         shooting = { x: Math.random() * w * 0.7 + w * 0.15, y: Math.random() * h * 0.35, vx: 2.6 + Math.random() * 2, vy: 1.4 + Math.random(), life: 1 };
182:       }
183:       if (shooting) {
184:         shooting.x += shooting.vx * 4; shooting.y += shooting.vy * 4; shooting.life -= 0.012;
185:         ctx.globalAlpha = Math.max(0, shooting.life) * 0.8;
186:         ctx.strokeStyle = '#f5e7c2'; ctx.lineWidth = 1.2;
187:         ctx.beginPath(); ctx.moveTo(shooting.x, shooting.y); ctx.lineTo(shooting.x - 70, shooting.y - 36); ctx.stroke();
188:         if (shooting.life <= 0) shooting = null;
189:       }
190:     }
191:     ctx.globalAlpha = 1;
192:     if (!reduced) requestAnimationFrame(draw);
193:   }
194:   resize();
195:   window.addEventListener('resize', resize);
196:   if (reduced) draw(0); else requestAnimationFrame(draw);
197: }
