207: function tone(freq, dur = 0.14, type = 'sine', vol = 0.035, delay = 0) {
208:   if (!soundOn) return;
209:   const ctx = audio(); if (!ctx) return;
210:   const t0 = ctx.currentTime + delay;
211:   const osc = ctx.createOscillator();
212:   const g = ctx.createGain();
213:   osc.type = type; osc.frequency.setValueAtTime(freq, t0);
214:   g.gain.setValueAtTime(0, t0);
215:   g.gain.linearRampToValueAtTime(vol, t0 + 0.015);
216:   g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
217:   osc.connect(g); g.connect(ctx.destination);
218:   osc.start(t0); osc.stop(t0 + dur + 0.02);
219: }
220: function playSound(kind) {
221:   if (!soundOn) return;
222:   if (kind === 'action') { tone(392, 0.18, 'sine', 0.03); tone(587, 0.22, 'sine', 0.02, 0.05); }
223:   else if (kind === 'turn') { tone(196, 0.5, 'sine', 0.03); tone(294, 0.45, 'sine', 0.02, 0.08); tone(392, 0.4, 'sine', 0.015, 0.16); }
224:   else if (kind === 'ascend') { [261, 329, 392, 523, 659].forEach((f, i) => tone(f, 1.1, 'sine', 0.028, i * 0.12)); tone(130, 1.4, 'triangle', 0.02); }
225:   else if (kind === 'error') { tone(150, 0.16, 'square', 0.016); }
226:   else if (kind === 'click') { tone(660, 0.05, 'sine', 0.02); }
227:   else if (kind === 'omen') { tone(220, 0.6, 'triangle', 0.02); tone(330, 0.5, 'sine', 0.015, 0.15); }
228: }
