657: function renderBoard(stand, might) {
658:   const entries = [
659:     ...state.rivals.map(r => ({ name: r.name, epithet: r.epithet, pantheon: r.pantheon, domain: r.domain, might: r.might, player: false })),
660:     { name: 'YOU', might, domain: state.god.domain, pantheon: state.god.pantheon, epithet: state.god.epithet, player: true },
661:   ].sort((a, b) => b.might - a.might);
662:   const playerIndex = entries.findIndex(e => e.player);
663:   const rows = entries.map((e, i) => {
664:     const playerRank = i + 1;
665:     if (!e.player && i >= 20) return '';
666:     const dd = domainOf(e.domain);
667:     const prev = state.lastRanks ? state.lastRanks[e.player ? 'YOU' : e.name] : null;
668:     let trend = '';
669:     if (prev) {
670:       const diff = prev - playerRank;
671:       if (diff > 0) trend = `<span class="t-trend up">▲ ${diff}</span>`;
672:       else if (diff < 0) trend = `<span class="t-trend down">▼ ${Math.abs(diff)}</span>`;
673:       else trend = `<span class="t-trend">—</span>`;
674:     }
675:     const prow = e.player;
676:     return `<li class="throne${prow ? ' you' : ''}${playerRank <= 3 ? ' top' : ''}" ${prow ? '' : `data-rival="${state.rivals.findIndex(r => r.name === e.name)}"`}>
677:       <span class="t-rank">${playerRank}</span>
678:       <span class="t-sigil" style="color:${dd.color}">${icon(DOMAIN_ICONS[dd.id])}</span>
679:       <span class="t-info"><span class="t-name">${esc(prow ? state.god.name : e.name)}${prow ? `<span class="you-tag">${esc(t('YOU'))}</span>` : ''}</span><span class="t-sub">${esc(domainName(dd))} · ${esc(t(e.pantheon))}</span></span>
680:       <span class="t-might">${fmt(e.might)}${trend}</span>
681:     </li>`;
682:   }).join('');
683:   $('#leaderboard').innerHTML = rows;
684:   $('#boardCrown').innerHTML = icon('crown');
685:   $('#playerStanding').innerHTML = `<span class="standing-text">${esc(t('Your standing'))}</span><span class="standing-badge">#${stand.rank} <span style="color:var(--muted-2);font-size:9px">${esc(t('of {n}', { n: stand.total }))}</span></span>`;
686:   if (playerIndex >= 20) {
687:     const note = document.createElement('div');
688:     note.className = 'standing-text';
689:     note.style.padding = '6px 4px 0';
690:     note.innerHTML = t('You are outside the Twenty Thrones. <b>{n}</b> might.', { n: fmt(might) });
691:     $('#playerStanding').prepend(note);
692:   }
693: }
