719:     state.followerDelta = res.changes ? res.changes.followers || 0 : 0;
720:     addLog(state, action.glyph, res.text, toneForAction(action.id), actionChronicleText(action.id, res));
721:     renderGame();
722:     flashAction(action.id);
723:     playSound('action');
724:     const summary = res.changes ? changeTags(res.changes).slice(0, 3).join(' · ') : (res.relic ? res.relic.name : t('Done'));
725:     toast(summary || t(action.name));
726:     if (canAscend(state)) toast(t('The way to {name} is open', { name: rankName(RANKS[state.rank + 1]) }), false);
727:     if (res.relic) setTimeout(() => openRelicModal(res.relic), 420);
